#!/usr/bin/env node
// Generates derived files from their canonical sources:
//   seed/tasks.json + seed/roadmap.json -> src/generated/seed.js  (bundled into the Worker)
//   src/schema/schemas.js               -> schemas/*.schema.json (for external tools and the GitHub Action)
// `node tools/build.mjs --check` fails if a generated file is stale (used by tests and CI).
import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { ALL_SCHEMAS } from '../src/schema/schemas.js';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const check = process.argv.includes('--check');

export function generated() {
  const tasks = JSON.parse(readFileSync(join(root, 'seed/tasks.json'), 'utf8'));
  const roadmap = JSON.parse(readFileSync(join(root, 'seed/roadmap.json'), 'utf8'));
  const files = {
    'src/generated/seed.js': `// GENERATED by tools/build.mjs from seed/*.json. Do not edit.\nexport const SEED = ${JSON.stringify({ tasks, roadmap }, null, 2)};\n`,
  };
  for (const [name, schema] of Object.entries(ALL_SCHEMAS)) files[`schemas/${name}`] = `${JSON.stringify(schema, null, 2)}\n`;
  files['public/onboarding.html'] = onboardingPage(readFileSync(join(root, 'docs/ONBOARDING.md'), 'utf8'));
  return files;
}

// Tiny Markdown subset -> HTML (headings, paragraphs, lists, fenced code, inline code, bold, links).
function escapeHtml(s) {
  return s.replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
}
function inline(s) {
  return escapeHtml(s)
    .replace(/`([^`]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/\[([^\]]+)\]\((https?:\/\/[^)\s]+|\/[^)\s]*)\)/g, '<a href="$2">$1</a>');
}
export function markdownToHtml(md) {
  const out = [];
  const lines = md.split('\n');
  let list = null;
  let para = [];
  const flushPara = () => { if (para.length) { out.push(`<p>${inline(para.join(' '))}</p>`); para = []; } };
  const flushList = () => { if (list) { out.push(`<${list.tag}>${list.items.map((i) => `<li>${inline(i)}</li>`).join('')}</${list.tag}>`); list = null; } };
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.startsWith('```')) {
      flushPara(); flushList();
      const code = [];
      for (i++; i < lines.length && !lines[i].startsWith('```'); i++) code.push(lines[i]);
      out.push(`<pre>${escapeHtml(code.join('\n'))}</pre>`);
      continue;
    }
    const h = /^(#{1,3})\s+(.*)$/.exec(line);
    if (h) { flushPara(); flushList(); out.push(`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`); continue; }
    const ul = /^\s*-\s+(.*)$/.exec(line);
    const ol = /^\s*\d+\.\s+(.*)$/.exec(line);
    if (ul || ol) {
      flushPara();
      const tag = ul ? 'ul' : 'ol';
      if (list && list.tag !== tag) flushList();
      if (!list) list = { tag, items: [] };
      list.items.push((ul || ol)[1]);
      continue;
    }
    if (/^\s{2,}\S/.test(line) && list) { list.items[list.items.length - 1] += ` ${line.trim()}`; continue; }
    if (!line.trim()) { flushPara(); flushList(); continue; }
    flushList();
    para.push(line.trim());
  }
  flushPara(); flushList();
  return out.join('\n');
}
function onboardingPage(md) {
  return `<!doctype html>
<!-- GENERATED by tools/build.mjs from docs/ONBOARDING.md. Do not edit. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Coordinator Onboarding</title>
<link rel="stylesheet" href="/style.css">
</head>
<body>
<main class="wrap doc">
<p><a href="/">← home</a></p>
${markdownToHtml(md)}
</main>
</body>
</html>
`;
}

const stale = [];
for (const [rel, content] of Object.entries(generated())) {
  const path = join(root, rel);
  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
  if (current === content) continue;
  if (check) stale.push(rel);
  else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${rel}`);
  }
}
if (check && stale.length) {
  console.error(`stale generated files (run npm run build): ${stale.join(', ')}`);
  process.exit(1);
}
